INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (52, 335, NULL, 'Why is his oxygen low?', 'The latest recorded SpO2 for Vikram Malhotra 1790408726344 is **N/A%** (recorded at 2026-09-26 13:15:39).\nConcurrently, the respiratory rate has changed from 18/min to 25/min and heart rate is 108 bpm.\n\n**Clinical Interpretation:**\nThis combination suggests acute respiratory compromise and compensatory physiological response (tachypnea and tachycardia secondary to increased work of breathing and hypoxic drive).\n\n**Documented Clinical Context:**\nThe patient\'s records document **Acute Bilateral Bacterial Pneumonia**, which provides essential clinical context for interpreting these physiological fluctuations.\n\n**Jeevan Setu Decision Support Assessment:**\n• Early Warning Score (EWS): **6** (HIGH Risk)\n• Composite Stability Index: **17%** (High Risk / Critical)\n• Current Recommendation: **CONTINUE_ICU** (Reason: Worsening oxygen saturation and tachypnea requiring intensive monitoring)\n\n*Clinical Note: The available database records indicate physiological concern, but database telemetry alone cannot establish a definitive single etiology without direct bedside clinical assessment by the treating team.*', 'cause_reason', 0.95, '2026-09-26 13:15:40');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (53, 335, NULL, 'Why is the patient\'s condition getting worse?', 'Based on the latest available records, the patient\'s condition demonstrates a **worsening physiological trend**.\n\n**Key Contributing Telemetry Findings:**\n• Respiratory Rate: 25/min (Worsening)\n• Heart Rate: 108 bpm (Worsening)\n• Systolic BP: 105 mmHg\n\n**Documented Clinical Context:**\nThe patient\'s records document **Acute Bilateral Bacterial Pneumonia**, which provides essential clinical context for interpreting these physiological fluctuations.\n\n**Jeevan Setu Decision Support Assessment:**\n• Early Warning Score (EWS): **6** (HIGH Risk)\n• Composite Stability Index: **17%** (High Risk / Critical)\n• Current Recommendation: **CONTINUE_ICU** (Reason: Worsening oxygen saturation and tachypnea requiring intensive monitoring)\n\n*Clinical Note: The available database records indicate physiological concern, but database telemetry alone cannot establish a definitive single etiology without direct bedside clinical assessment by the treating team.*', 'cause_reason', 0.95, '2026-09-26 13:15:41');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (54, 335, NULL, 'Is he going to die?', 'I cannot determine from the available data whether the patient will die, and no clinical decision support system should make definitive mortality predictions from database telemetry measurements alone.\n\nHowever, the current records for **Vikram Malhotra 1790408726344** (UHID-2026-00067) show important concerning physiological findings:\n\n• Respiratory Rate: **25/min** (trend: Worsening from 18/min)\n• Heart Rate: **108 bpm**\n• Blood Pressure: **105 mmHg**\n• Level of Consciousness: **Alert**\n• Early Warning Score (EWS): **6** (HIGH Risk)\n• Composite Stability Index: **17%** (High Risk / Critical)\n• Telemetry Timestamp: 2026-09-26 13:15:39\n\n**Jeevan Setu Clinical Assessment:**\nThe current recommendation is **CONTINUE_ICU** due to: Worsening oxygen saturation and tachypnea requiring intensive monitoring.\n\n**Action Required:**\nThese findings indicate active physiological compromise. This situation requires immediate bedside assessment and continuous monitoring by the treating ICU / critical care clinical team.', 'prognosis_mortality', 0.98, '2026-09-26 13:15:42');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (55, 335, NULL, 'Is he getting better?', '**Yes, the available recent readings show a worsening physiological trend for Vikram Malhotra 1790408726344.**\n\n**Trajectory Breakdown:**\n• Respiratory Rate: Worsening ↑ (18/min → 25/min)\n• Heart Rate: Worsening ↑ (82 bpm → 108 bpm)\n• Systolic BP: Stable → (120 mmHg → 105 mmHg)\n• Temperature: Worsening ↑ (37.2 °C → 38.5 °C)\n\n• Current EWS Score: **6** (HIGH Risk)\n• Latest Telemetry Recorded: 2026-09-26 13:15:39', 'deterioration_improvement', 0.98, '2026-09-26 13:15:42');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (56, 335, NULL, 'Patient is unconscious and SpO2 is 78. What should I do?', '🚨 **CRITICAL EMERGENCY PROTOCOL ACTIVATED** 🚨\n\n**IMMEDIATE CLINICAL ACTION REQUIRED:**\nThe reported presentation represents an acute, potentially life-threatening clinical situation.\n1. Immediately initiate emergency critical care assessment (Airway, Breathing, Circulation).\n2. Alert the attending ICU specialist and Medical Emergency Team (MET) / Code Blue team.\n3. Verify patent airway and deliver high-flow supplemental oxygen as clinically indicated.\n\n**Latest Stored Telemetry for Vikram Malhotra 1790408726344 (UHID-2026-00067):**\n• SpO2: N/A% | RR: 25/min | HR: 108 bpm\n• Blood Pressure: 105 mmHg | Consciousness: Alert\n• Current EWS Score: 6 (HIGH Risk)\n\n*Do not delay bedside intervention for software queries.*', 'emergency_critical', 0.98, '2026-09-26 13:15:42');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (57, 335, NULL, 'What does low SpO2 mean?', '**General Clinical Concept:**\nOxygen saturation (SpO2) measures the percentage of hemoglobin binding sites occupied by oxygen. In adults, normal SpO2 is typically ≥95% on room air. Values below 92% indicate significant hypoxemia requiring oxygen supplementation and investigation of underlying pulmonary or cardiac etiologies.', 'general_medical', 0.95, '2026-09-26 13:15:42');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (58, 336, NULL, 'What is the current heart rate?', 'The latest recorded Heart Rate for Rahul Sharma 1790408743207 is **115 bpm**, recorded at 2026-09-26 13:15:44.\n\n• Previous readings: 105 bpm, 92 bpm, 80 bpm, indicating a **worsening** trend.\n• Parameter Band: **Caution** (EWS Contribution: +2)', 'vitals_query', 0.92, '2026-09-26 13:15:44');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (59, 336, NULL, 'How has the SpO2 changed?', '**Vital Parameter Trends for Rahul Sharma 1790408743207 (UHID-2026-00068):**\n\nOver the last 4 recorded readings: Respiratory Rate changed from 18/min to 26/min (Worsening ↑); Heart Rate changed from 80 bpm to 115 bpm (Worsening ↑); Systolic BP changed from 120 mmHg to 102 mmHg (Stable →); Temperature changed from 37°C to 38.6°C (Worsening ↑).', 'trends_query', 0.92, '2026-09-26 13:15:44');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (60, 336, NULL, 'What is the EWS score and stability index?', '**Early Warning Score (EWS)** for Rahul Sharma 1790408743207 (UHID-2026-00068):\n• EWS Score: **7**\n• Risk Stratification: **CRITICAL**\n• Composite Stability Index: **14%** (Critical)\n• Telemetry Timestamp: 2026-09-26 13:15:44', 'ews_query', 0.95, '2026-09-26 13:15:44');
INSERT INTO `chatbot_conversations` (`conversation_id`, `user_id`, `patient_id`, `user_message`, `bot_response`, `intent`, `confidence`, `created_at`) VALUES (61, 336, NULL, 'Why is this patient in ICU?', 'Based on the latest available records, the patient\'s condition demonstrates a **worsening physiological trend**.\n\n**Key Contributing Telemetry Findings:**\n• Respiratory Rate: 26/min (Worsening)\n• Heart Rate: 115 bpm (Worsening)\n• Systolic BP: 102 mmHg\n\n**Documented Clinical Context:**\nThe patient\'s records document **Severe Acute Respiratory Infection & Sepsis**, which provides essential clinical context for interpreting these physiological fluctuations.\n\n**Jeevan Setu Decision Support Assessment:**\n• Early Warning Score (EWS): **7** (CRITICAL Risk)\n• Composite Stability Index: **14%** (Critical)\n• Current Recommendation: **CONTINUE_ICU** (Reason: Severe respiratory decompensation with elevated EWS)\n\n*Clinical Note: The available database records indicate physiological concern, but database telemetry alone cannot establish a definitive single etiology without direct bedside clinical assessment by the treating team.*', 'cause_reason', 0.95, '2026-09-26 13:15:44');
