INSERT INTO `reports` (`report_id`, `patient_id`, `report_type`, `title`, `content`, `file_path`, `generated_by`, `created_at`) VALUES (1, 1, 'daily', 'Daily Progress Report — Rajesh Kumar', 'Patient Name: Rajesh Kumar | Ward: ICU-A01 | Diagnosis: Acute Myocardial Infarction\n\nClinical Summary: Patient admitted 72 hours ago with STEMI. Initial EWS was critical (score 7+). Received primary PCI and started on dual antiplatelet therapy. Hemodynamics improving over last 24 hours. Latest vitals: HR 92 bpm, BP 105/68 mmHg, RR 18/min, Temp 37.4°C. EWS trending downward.\n\nPlan: Continue monitoring. Consider HDU step-down if EWS remains < 3 for next 12 hours.', NULL, 2, '2026-09-23 18:54:13');
INSERT INTO `reports` (`report_id`, `patient_id`, `report_type`, `title`, `content`, `file_path`, `generated_by`, `created_at`) VALUES (2, 5, 'daily', 'Daily Progress Report — Mohammed Ali', 'Patient Name: Mohammed Ali | Ward: ICU-A05 | Diagnosis: Acute Respiratory Distress Syndrome\n\nClinical Summary: Patient admitted 24 hours ago with ARDS secondary to viral pneumonia. Remains on mechanical ventilation with FiO2 0.6. EWS consistently in critical range (score > 7). Latest vitals: HR 118 bpm, BP 82/55 mmHg, RR 28/min, Temp 38.8°C.\n\nPlan: Continue lung-protective ventilation. Titrate vasopressors. Prone positioning q12h. Multidisciplinary team review scheduled.', NULL, 3, '2026-09-23 18:54:13');
